/*
 * PLC HW mapping for STM32H743 (our current board config)
 *
 * DI0..DI7  -> PD0, PD1, PD3, PD5, PD7, PD8, PG0, PG1 (Pull-Up recommended)
 * DO0..DO7  -> PE0..PE7 (Active High recommended)
 *
 * PWM mapping: example via TIM3/TIM4 (adjust to your CubeMX timers/pins).
 */

/* ----- External HAL handles generated by CubeMX ----- */
extern IWDG_HandleTypeDef hiwdg;

// PWM timers (adjust if you use other timers)
extern TIM_HandleTypeDef  htim1;
extern TIM_HandleTypeDef  htim3;

// UART if needed in other parts (kept as in your original)
extern UART_HandleTypeDef huart3;

/* ADC DMA buffer declared somewhere else (as in your project) */

/* ------------------------------------------------------------------------- */
/*                            Mapping tables                                  */
/* ------------------------------------------------------------------------- */

typedef struct {
    GPIO_TypeDef* port;
    uint16_t      pin;
    bool          inverted;
} HwDiscreteInMap;

typedef struct {
    GPIO_TypeDef* port;
    uint16_t      pin;
    bool          inverted;
} HwDiscreteOutMap;

typedef struct {
    uint8_t bufIndex;
    float   scale;
} HwAnalogInMap;

typedef struct {
    TIM_HandleTypeDef* htim;
    uint32_t           channel;
} HwPwmOutMap;

/* ------------------------------------------------------------------------- */
/*                      Concrete mapping for STM32H743                         */
/* ------------------------------------------------------------------------- */

/* DI0..DI7 */
static const HwDiscreteInMap hw_di[] = {
        { GPIOD, GPIO_PIN_0, false },  // DI0
        { GPIOD, GPIO_PIN_1, false },  // DI1
        { GPIOD, GPIO_PIN_3, false },  // DI2
        { GPIOD, GPIO_PIN_5, false },  // DI3
        { GPIOD, GPIO_PIN_7, false },  // DI4
        { GPIOD, GPIO_PIN_8, false },  // DI5
        { GPIOG, GPIO_PIN_0, false },  // DI6
        { GPIOG, GPIO_PIN_1, false },  // DI7
};

/* DO0..DO7 */
static const HwDiscreteOutMap hw_do[] = {
        { GPIOE, GPIO_PIN_0, false },  // DO0
        { GPIOE, GPIO_PIN_1, false },  // DO1
        { GPIOE, GPIO_PIN_2, false },  // DO2
        { GPIOE, GPIO_PIN_3, false },  // DO3
        { GPIOE, GPIO_PIN_4, false },  // DO4
        { GPIOE, GPIO_PIN_5, false },  // DO5
        { GPIOE, GPIO_PIN_6, false },  // DO6
        { GPIOE, GPIO_PIN_7, false },  // DO7
};

/* AI mapping (оставь как у тебя по факту g_adcRaw[])
 * Если сейчас у тебя, например, 8 каналов ADC DMA -> bufIndex 0..7
 * Если AI пока не настроен — можешь оставить пустым массивом.
 */
static const HwAnalogInMap hw_ai[] = {
        { 0, 1.0f }, // AI0 -> g_adcRaw[0]
        { 1, 1.0f }, // AI1 -> g_adcRaw[1]
        { 2, 1.0f }, // AI2 -> g_adcRaw[2]
        { 3, 1.0f }, // AI3 -> g_adcRaw[3]
        { 4, 1.0f }, // AI4 -> g_adcRaw[4]
        { 5, 1.0f }, // AI5 -> g_adcRaw[5]
        { 6, 1.0f }, // AI6 -> g_adcRaw[6]
        { 7, 1.0f }, // AI7 -> g_adcRaw[7]
};

/* PWM mapping example (8 каналов):
 * PWM0..PWM3 -> TIM3 CH1..CH4
 * PWM4..PWM7 -> TIM4 CH1..CH4
 *
 * Если PWM пока не нужен — сделай hw_pwm[] пустым и hw_pwm_count=0.
 */
static const HwPwmOutMap hw_pwm[] = {
        { &htim3, TIM_CHANNEL_1 }, // PWM0
        { &htim3, TIM_CHANNEL_2 }, // PWM1
        { &htim3, TIM_CHANNEL_3 }, // PWM2
        { &htim3, TIM_CHANNEL_4 }, // PWM3
        { &htim1, TIM_CHANNEL_1 }, // PWM4
        { &htim1, TIM_CHANNEL_2 }, // PWM5
        { &htim1, TIM_CHANNEL_3 }, // PWM6
        { &htim1, TIM_CHANNEL_4 }, // PWM7
};

/* Sizes */
static const uint16_t hw_di_count  = (uint16_t)(sizeof(hw_di)  / sizeof(hw_di[0]));
static const uint16_t hw_do_count  = (uint16_t)(sizeof(hw_do)  / sizeof(hw_do[0]));
static const uint16_t hw_ai_count  = (uint16_t)(sizeof(hw_ai)  / sizeof(hw_ai[0]));
static const uint16_t hw_pwm_count = (uint16_t)(sizeof(hw_pwm) / sizeof(hw_pwm[0]));

/* ------------------------------------------------------------------------- */
/* Helpers                                                                    */
/* ------------------------------------------------------------------------- */

/* Get ARR safely via HAL macro */
static inline uint32_t timer_get_arr(TIM_HandleTypeDef* htim)
{
    // ARR register value (auto-reload)
    return __HAL_TIM_GET_AUTORELOAD(htim);
}

/* Set compare safely via HAL macro */
static inline void timer_set_ccr(TIM_HandleTypeDef* htim, uint32_t channel, uint32_t value)
{
    __HAL_TIM_SET_COMPARE(htim, channel, value);
}

/* ------------------------------------------------------------------------- */
/* plc.h functions                                                            */
/* ------------------------------------------------------------------------- */

uint32_t now_ms(void)
{
    return (uint32_t)(xTaskGetTickCount() * portTICK_PERIOD_MS);
}

void iwdg_feed(void)
{
//    HAL_IWDG_Refresh(&hiwdg);
}

bool hw_read_discrete_input(int logicalCh)
{
    if (logicalCh < 0 || logicalCh >= (int)hw_di_count) {
        return false;
    }

    const HwDiscreteInMap* m = &hw_di[logicalCh];

    GPIO_PinState raw = HAL_GPIO_ReadPin(m->port, m->pin);
    bool v = (raw == GPIO_PIN_SET);

    if (m->inverted) {
        v = !v;
    }
    return v;
}

void hw_write_discrete_output(int logicalCh, bool val)
{
    if (logicalCh < 0 || logicalCh >= (int)hw_do_count) {
        return;
    }

    const HwDiscreteOutMap* m = &hw_do[logicalCh];
    bool phys = m->inverted ? !val : val;

    HAL_GPIO_WritePin(m->port, m->pin, phys ? GPIO_PIN_SET : GPIO_PIN_RESET);
}

static inline void adc_invalidate_cache(void)
{
    // Важно: размер в байтах, адрес и размер должны быть кратны 32 (у тебя aligned(32) уже ок)
    SCB_InvalidateDCache_by_Addr((uint32_t*)g_adcRaw, sizeof(g_adcRaw));
}

int32_t hw_read_adc_input(int logicalCh)
{
    if (logicalCh < 0 || logicalCh >= (int)hw_ai_count) {
        return 0;
    }

    const HwAnalogInMap* m = &hw_ai[logicalCh];

    // На Cortex-M7 чтение 16-bit атомарно, но DMA может обновлять.
    // Для PLC статуса этого достаточно. Если нужна строгая согласованность —
    // сделаем копию буфера в callback DMA.
    uint32_t raw32 = g_adcRaw[m->bufIndex];
    uint16_t raw12 = (uint16_t)(raw32 & 0xFFFFu); // обычно данные в младших битах
    return (int32_t)raw12;
}

void hw_write_pwm_output(int logicalCh, int dutyPercent)
{
    if (logicalCh < 0 || logicalCh >= (int)hw_pwm_count) {
        return;
    }

    const HwPwmOutMap* m = &hw_pwm[logicalCh];

    if (dutyPercent < 0)   dutyPercent = 0;
    if (dutyPercent > 100) dutyPercent = 100;

    uint32_t arr = timer_get_arr(m->htim);
    // CCR range: 0..ARR (обычно)
    uint32_t ccr = (arr * (uint32_t)dutyPercent) / 100u;

    timer_set_ccr(m->htim, m->channel, ccr);
}

void plc_hw_reset_outputs(void)
{
    // 1) All DO -> OFF
    for (uint16_t i = 0; i < hw_do_count; i++) {
        hw_write_discrete_output((int)i, false);
    }

    // 2) All PWM -> 0%
    for (uint16_t i = 0; i < hw_pwm_count; i++) {
        hw_write_pwm_output((int)i, 0);
    }
}
